import{_ as r,c as l,o as t,ag as e}from"./chunks/framework.Bkod66qp.js";const g=JSON.parse('{"title":"서울특별시 재단법인 서울문화재단","description":"","frontmatter":{"title":"서울특별시 재단법인 서울문화재단","subtitle":"","doc_id":"","last_update":"2023-12-29","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/101_서울특별시 재단법인 서울문화재단 설립 및 운영에 관한 조례(231229).md","filePath":"regulation/101_서울특별시 재단법인 서울문화재단 설립 및 운영에 관한 조례(231229).md"}'),n={name:"regulation/101_서울특별시 재단법인 서울문화재단 설립 및 운영에 관한 조례(231229).md"};function o(s,a,i,d,c,h){return t(),l("div",null,a[0]||(a[0]=[e(`<h1 id="law-title" class="center" tabindex="-1">서울특별시 재단법인 서울문화재단 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;서울특별시 재단법인 서울문화재단 {#law-title .center}&quot;">​</a></h1><p>설립 및 운영에 관한 조례</p><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2003.   7.  15
개정 2009.   5.  28
개정 2011.   7.  28
개정 2012.   1.   5
개정 2012.  12.  31
개정 2013.   8.   1
개정 2015.  10.   8
개정 2016.   1.   7
개정 2018.   1.   4
개정 2019.   1.   3
개정 2019.  12.  31
개정 2021.   9.  30
개정 2022.   3.  10
개정 2023.  12.  29</pre></div><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 조례는 시민의 자율적인 문화예술활동을 진작시켜 서울의 문화예술진흥을 도모하기 위하여 문화예술진흥과 시민의 문화예술활동 지원을 목적으로 하는 재단법인 서울문화재단(이하 &quot;재단&quot;이라 한다)의 설립·운영에 필요한 사항을 규정함을 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (설립) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (설립) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(설립)</strong> 재단은 민법의 규정에 의한 재단법인으로 설립한다.</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (업무) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (업무) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(업무)</strong> 재단은 다음 각 호의 업무를 수행한다.</p><ol><li>문화예술의 창작·보급 및 문화예술활동의 지원</li><li>문화예술의 교육 및 연구</li><li>국내·외 문화예술 교류</li><li>청소년, 청년, 미혼남녀, 장애인, 노인 등 시민의 문화향수 및 창의력 증진 &lt;개정 2009. 5. 28., 2023. 12. 29.&gt;</li><li>지역문화의 육성·지원 및 지역문화 전문인력 양성 &lt;신설 2015. 10. 8.&gt;</li><li>그 밖에 법인의 목적달성에 필요한 사업 &lt;개정 2019. 12. 31.&gt;</li></ol><h2 id="article4" class="sr-only" tabindex="-1">제4조 (기본재산) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (기본재산) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(기본재산)</strong> ① 재단의 기본재산은 다음 각 호의 재원으로 조성한다.</p><ol><li>서울특별시(이하 &quot;시&quot;라 한다)의 출연금 및 재산 &lt;개정 2016. 1. 7.&gt;</li><li>제1호 이외의 자의 기부금</li><li>사업 수익금</li><li>그 밖의 수입금 &lt;개정 2019. 12. 31.&gt;<br> ② 제1항의 기본재산 조성을 위한 시의 출연금 한도액을 1,000억원으로 한다.<br> ③ 재단은 기본재산 총액의 5% 이상 혹은 50억원 이상의 기본재산을 취득하거나 처분하는 경우에 사전에 서울특별시의회 소관 상임위원회에 보고하여야 한다.&lt;신설 2013. 8. 1.&gt;<br> ④ 시는 재단의 설립·운영 및 사업에 필요한 경비 등을 예산의 범위에서 재단에 출연할 수 있다. &lt;신설 2016. 1. 7.&gt;</li></ol><h2 id="article5" class="sr-only" tabindex="-1">제5조 (정관) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (정관) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(정관)</strong> ① 재단은 정관에 민법 제40조 제1호 내지 제5호의 사항 이외에 다음 각 호의 사항을 기재하여야 한다.</p><ol><li>임원 및 직원에 관한 사항</li><li>이사회에 관한 사항</li><li>사업과 그 수행에 관한 사항</li><li>회계에 관한 사항</li><li>공고의 방법에 관한 사항</li><li>정관의 변경에 관한 사항</li><li>해산에 관한 사항</li><li>그 밖에 재단의 운영에 필요한 사항 &lt;개정 2019. 12. 31.&gt;<br> ② 재단은 정관을 변경하고자 하는 때에는 주무관청에 정관변경 허가 신청을 하기 전에 서울특별시장(이하 &quot;시장&quot;이라 한다)의 승인을 얻어야 한다. 이 경우 사전에 서울특별시의회 소관 상임위원회에 보고하여야 한다.&lt;개정 2011. 7. 28., 2012. 12. 31.&gt;</li></ol><h2 id="article6" class="sr-only" tabindex="-1">제6조 (임원) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (임원) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(임원)</strong> ① 재단은 정관에 따라 이사장 및 대표이사를 포함한 15명 이내의 이사와 2명의 감사를 두되, 이사는 문화예술에 관한 식견과 덕망이 있는 각계 인사로 한다. &lt;개정 2011. 7. 28.&gt;<br> ② 대표이사를 제외한 임원은 비상근으로 한다.</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (임원의 직무) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (임원의 직무) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(임원의 직무)</strong> ① 대표이사는 재단을 대표하고, 그 업무를 통할한다.<br> ② 감사는 재단의 업무와 회계를 감사하며, 이사회에 출석하여 의견을 진술할 수 있다.</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (이사회) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (이사회) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(이사회)</strong> ① 재단에 이사회를 두되, 이사회는 이사장과 이사로 구성한다. 다만, 이사회 구성 시 특정 성(性)이 60%를 초과하지 않도록 노력한다. &lt;개정 2018. 1. 4.&gt;<br> ② 이사회는 정관이 정하는 바에 따라 재단의 업무에 관한 중요사항을 심의·의결한다.<br> ③ 이사장은 필요하다고 인정하는 때에 이사회를 소집하고, 그 의장이 되어 회무를 통할한다.<br> ④ 이사장이 부득이한 사유로 그 직무를 수행하지 못하는 때에는 대표이사가 그 직무를 대행한다.<br> ⑤ 이사회는 재적인원 과반수의 출석과 출석인원 과반수의 찬성으로 의결한다.</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (임원의 임면 등) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (임원의 임면 등) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(임원의 임면 등)</strong> ① 이사장과 대표이사는 각각 시장이 임면한다. &lt;개정 2012. 1. 5.&gt;<br> ② 임원의 임기는 3년으로 하고, 1년 단위로 연임될 수 있으며, 그 밖에 임원의 임면에 관한 사항은 정관이 정하는 바에 따른다. &lt;개정 2011. 7. 28., 2012. 1. 5., 2019. 1. 3., 2022. 3. 10.&gt;<br> ③ 삭제 &lt;2012. 1. 5.&gt;</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (직원) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (직원) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(직원)</strong> 재단의 직원은 정관이 정하는 바에 의하여 대표이사가 임면한다.</p><h2 id="article11" class="sr-only" tabindex="-1">제11조 (수익사업) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (수익사업) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(수익사업)</strong> 재단은 설립목적의 범위안에서 시장의 사전승인을 얻어 수익사업을 할 수 있다.</p><h2 id="article12" class="sr-only" tabindex="-1">제12조 (사업연도) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (사업연도) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(사업연도)</strong> 재단의 사업연도는 지방자치단체의 회계연도에 따른다.</p><h2 id="article13" class="sr-only" tabindex="-1">제13조 (업무계획 등) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (업무계획 등) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(업무계획 등)</strong> ① 재단은 사업연도마다 업무계획과 예산서를 작성하여 사업연도 개시 1월 전까지 시장의 승인을 얻어야 한다. 이를 변경하고자 하는 때에도 또한 같다.<br> ② 재단은 사업연도마다 결산서를 작성하여 시장이 지정하는 공인회계사의 회계감사를 받아 해당 사업연도 종료후 2월 이내에 시장에게 제출하여야 한다. &lt;개정 2011. 7. 28., 2019. 12. 31., 2021. 9. 30.&gt;</p><h2 id="article14" class="sr-only" tabindex="-1">제14조 (사업의 대행) <a class="header-anchor" href="#article14" aria-label="Permalink to &quot;제14조 (사업의 대행) {#article14 .sr-only}&quot;">​</a></h2><p><strong>제14조(사업의 대행)</strong> 재단은 국가·시 또는 자치구의 문화시설 운영 또는 문화진흥 사업을 위탁받아 수행하거나 대행할 수 있으며, 이 경우 필요한 비용부담은 국가·시 또는 자치구가 부담한다.</p><h2 id="article15" class="sr-only" tabindex="-1">제15조 (공무원의 파견요청) <a class="header-anchor" href="#article15" aria-label="Permalink to &quot;제15조 (공무원의 파견요청) {#article15 .sr-only}&quot;">​</a></h2><p><strong>제15조(공무원의 파견요청)</strong> 재단은 재단의 업무수행을 위하여 필요한 경우에 시장에게 소속 공무원의 파견요청을 할 수 있다.</p><h2 id="article16" class="sr-only" tabindex="-1">제16조 (감독) <a class="header-anchor" href="#article16" aria-label="Permalink to &quot;제16조 (감독) {#article16 .sr-only}&quot;">​</a></h2><p><strong>제16조(감독)</strong> ① 시장은 재단의 업무를 감독한다.<br> ② 시장은 재단의 업무에 관하여 필요한 사항의 보고를 받거나 소속 공무원으로 하여금 검사하게 할 수 있다.</p><h2 id="article17" class="sr-only" tabindex="-1">제17조 (재정지원) <a class="header-anchor" href="#article17" aria-label="Permalink to &quot;제17조 (재정지원) {#article17 .sr-only}&quot;">​</a></h2><p><strong>제17조(재정지원)</strong> 시장은 재단에 대하여 예산의 범위안에서 운영비 및 사업비를 지원할 수 있다.</p><h2 id="article18" class="sr-only" tabindex="-1">제18조 (규칙) <a class="header-anchor" href="#article18" aria-label="Permalink to &quot;제18조 (규칙) {#article18 .sr-only}&quot;">​</a></h2><p><strong>제18조(규칙)</strong> 이 조례의 시행에 관하여 필요한 사항은 규칙으로 정한다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2003. 7. 15.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2009. 5. 28.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum3" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum3" aria-label="Permalink to &quot;부칙 {#addendum3 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2011. 7. 28.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum4" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum4" aria-label="Permalink to &quot;부칙 {#addendum4 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2012. 1. 5.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum5" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum5" aria-label="Permalink to &quot;부칙 {#addendum5 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2012. 12. 31.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum6" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum6" aria-label="Permalink to &quot;부칙 {#addendum6 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2013. 8. 1.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum7" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum7" aria-label="Permalink to &quot;부칙 {#addendum7 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2015. 10. 8.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum8" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum8" aria-label="Permalink to &quot;부칙 {#addendum8 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2016. 1. 7.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum9" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum9" aria-label="Permalink to &quot;부칙 {#addendum9 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2018. 1. 4.&gt;<br> 제1조(시행일) 이 조례는 공포한 날부터 시행한다.<br> 제2조(이사회 구성의 적용례) 제8조제1항의 개정규정은 이 조례 시행 후 이사회 구성원의 결원 또는 임기만료의 사유 등으로 새로이 임명하는 경우부터 적용한다.</p><h2 id="addendum10" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum10" aria-label="Permalink to &quot;부칙 {#addendum10 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2019. 1. 3.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum11" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum11" aria-label="Permalink to &quot;부칙 {#addendum11 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2019. 12. 31.&gt;</p><p style="text-align:center;">(서울특별시 자치법규 일본식 표현 일괄정비 조례)</p> 이 조례는 공포한 날부터 시행한다. <h2 id="addendum12" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum12" aria-label="Permalink to &quot;부칙 {#addendum12 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2021. 9. 30.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum13" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum13" aria-label="Permalink to &quot;부칙 {#addendum13 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2022. 3. 10.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p><h2 id="addendum14" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum14" aria-label="Permalink to &quot;부칙 {#addendum14 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2023. 12. 29.&gt;<br> 이 조례는 공포한 날부터 시행한다.</p>`,72)]))}const b=r(n,[["render",o]]);export{g as __pageData,b as default};
